class Temperature:
    def __init__(self, celsius: float = 0.0):
        self._celsius = celsius

    @property
    def celsius(self) -> float:
        """섭씨 온도 프로퍼티 게터"""
        return self._celsius

    @celsius.setter
    def celsius(self, value: float):
        """섭씨 온도 프로퍼티 세터 (유효성 검증)"""
        if value < -273.15:
            raise ValueError("절대영도(-273.15°C) 미만으로 설정할 수 없습니다.")
        self._celsius = value

    @property
    def fahrenheit(self) -> float:
        """화씨 온도로 변환 계산하는 읽기 전용 프로퍼티"""
        return self._celsius * 9 / 5 + 32

t = Temperature(25)
print(f"섭씨: {t.celsius}°C, 화씨: {t.fahrenheit}°F") # 25°C, 77°F
t.celsius = 30 # setter 호출
print(f"수정 후 화씨: {t.fahrenheit}°F") # 86°F
