class Coordinate:
    __slots__ = ("x", "y") # __dict__를 생성하지 않고 지정된 속성만 허용

    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    @classmethod
    def from_string(cls, coord_str: str):
        """대안 생성자 (팩토리 메서드)"""
        x_str, y_str = coord_str.split(",")
        return cls(float(x_str.strip()), float(y_str.strip()))

    @staticmethod
    def manhattan_distance(p1, p2) -> float:
        """인스턴스 상태와 무관한 순수 유틸리티"""
        return abs(p1.x - p2.x) + abs(p1.y - p2.y)

p1 = Coordinate(10.0, 20.0)
p2 = Coordinate.from_string("30.0, 50.0")
print(f"거리: {Coordinate.manhattan_distance(p1, p2)}") # 50.0
# p1.z = 100 # AttributeError! __slots__에 정의되지 않은 새 속성 추가 차단

