class DataSet:
    def __init__(self, name: str, items: list):
        self.name = name
        self.items = list(items)

    def __len__(self) -> int:
        return len(self.items)

    def __getitem__(self, idx):
        return self.items[idx]

    def __repr__(self) -> str:
        """개발자를 위한 명확하고 재현 가능한 표현"""
        return f"DataSet(name={self.name!r}, items={self.items!r})"

    def __str__(self) -> str:
        """사용자 친화적인 출력"""
        return f"[{self.name}] 데이터셋 ({len(self.items)}개 항목)"

    def __call__(self, multiplier: int):
        """인스턴스를 함수처럼 호출 가능하게 만듦"""
        return [x * multiplier for x in self.items]

ds = DataSet("Scores", [10, 20, 30])
print(repr(ds))      # DataSet(name='Scores', items=[10, 20, 30])
print(str(ds))       # [Scores] 데이터셋 (3개 항목)
print(len(ds))       # 3
print(ds[1])         # 20 (__getitem__ 지원 덕분에 인덱싱과 슬라이싱 가능)
print(ds(2))         # [20, 40, 60] (__call__ 호출)

