class RangeStep:
    """부동소수점 스텝을 지원하는 커스텀 이터러블/이터레이터"""
    def __init__(self, start: float, stop: float, step: float):
        self.current = start
        self.stop = stop
        self.step = step

    def __iter__(self):
        return self # 이터레이터 자신 반환

    def __next__(self) -> float:
        if self.current >= self.stop:
            raise StopIteration # 순회 종료 신호
        val = self.current
        self.current += self.step
        return round(val, 4)

# for 루프 순회
for x in RangeStep(0.0, 1.0, 0.25):
    print(x, end=" | ") # 0.0 | 0.25 | 0.5 | 0.75 |
print()

# next()와 기본값 매개변수 (StopIteration 방지)
it = iter(RangeStep(10, 11, 0.5))
print("1st:", next(it))
print("2nd:", next(it))
print("3rd:", next(it, "종료됨")) # 기본값 지정

