class DatabaseConnectionError(Exception):
    """커스텀 애플리케이션 예외"""
    pass

def query_user(user_id: int):
    try:
        if user_id <= 0:
            raise ValueError("유효하지 않은 사용자 ID")
        result = {"id": user_id, "name": "Alice"}
    except ValueError as ve:
        # 예외 체이닝 (Exception Chaining)
        raise DatabaseConnectionError("사용자 조회 파이프라인 에러") from ve
    else:
        print(">> 쿼리 성공!")
        return result
    finally:
        print(">> DB 커넥션 풀 반환 완료 (항상 실행)")

try:
    query_user(-1)
except DatabaseConnectionError as err:
    print(f"최종 포착: {err}")
    print(f"원인 예외: {err.__cause__}") # ValueError 객체 보존

