import functools
import time

def retry(max_attempts: int = 3, delay: float = 0.01):
    """매개변수를 받는 커스텀 재시도 데코레이터"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_err = None
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_err = e
                    print(f"[{func.__name__}] 시도 {attempt} 실패: {e}")
                    time.sleep(delay)
            raise RuntimeError(f"{max_attempts}회 재시도 실패") from last_err
        return wrapper
    return decorator

@retry(max_attempts=2)
def unreliable_api(x: int) -> int:
    """불안정한 API 호출 함수"""
    if x < 0:
        raise ValueError("음수 입력 불가")
    return x * 10

print("결과:", unreliable_api(5))
print("함수 메타데이터 유지 확인:", unreliable_api.__name__, unreliable_api.__doc__)

